checks.run:
R="acme/app"; f=.moor/artifacts/alerts.tsv
[ "$(head -1 $f 2>/dev/null)" = "$(printf 'repo\titem\taction\treason')" ] || { echo "alerts.tsv is missing or lacks its header line"; exit 1; }
bad=$(awk -F'\t' 'NR>1 && (NF<4 || $3 !~ /^(fix|dismiss|person|merge|skip)$/ || $4 == "")' $f | head -3); [ -z "$bad" ] || { echo "rows need repo, item, fix|dismiss|person|merge|skip and a reason: $bad"; exit 1; }
t=$(date -u -r $f +%Y-%m-%dT%H:%M:%SZ); miss=
for r in $R; do
  ns=$(gh api --paginate "repos/$r/dependabot/alerts?state=open&per_page=100" --jq ".[]|select(.created_at<\"$t\")|.number") || { echo "cannot read the alerts of $r"; exit 1; }
  ps=$(gh api --paginate "repos/$r/pulls?state=open&per_page=100" --jq ".[]|select(.user.login==\"dependabot[bot]\" and .created_at<\"$t\")|\"pr\"+(.number|tostring)") || { echo "cannot read the pull requests of $r"; exit 1; }
  for n in $ns $ps; do awk -F'\t' -v r=$r -v n=$n '$1==r && $2==n {f=1} END {exit !f}' $f || miss="$miss $r:$n"; done
done
[ -z "$miss" ] || { echo "open on GitHub but not in alerts.tsv:$miss"; exit 1; }; echo "alerts.tsv names every open alert and Dependabot PR"

R="acme/app"; f=.moor/artifacts/upgrade-prs.txt
[ -s $f ] || { echo "no upgrade-prs.txt"; exit 1; }
[ "$(tr -d ' \n' < $f)" = none ] && { echo "nothing upgraded"; exit 0; }
for u in $(cat $f); do
  p=${u#https://github.com/}; r=${p%/pull/*}; n=${p##*/pull/}
  case " $R " in *" $r "*) ;; *) echo "$u is not a PR on this workflow's repos"; exit 1;; esac
  d=$(gh api repos/$r --jq .default_branch) || { echo "cannot read $r"; exit 1; }
  got=$(gh api repos/$r/pulls/$n --jq '.state+" "+.base.ref+" "+.head.ref') || { echo "cannot read $u"; exit 1; }
  set -- $got; [ "$1" = open ] || { echo "$u is $1"; exit 1; }; [ "$2" = "$d" ] || { echo "$u targets $2, not $d"; exit 1; }; [ "$3" != "$d" ] || { echo "$u comes from $d itself"; exit 1; }
done; echo "every upgrade PR is open against the default branch"

S="docker android ios"; f=.moor/artifacts/live.tsv; up=.moor/artifacts/upgrade-prs.txt; al=.moor/artifacts/alerts.tsv
[ "$(head -1 $f 2>/dev/null)" = "$(printf 'surface\tref\tresult\treason')" ] || { echo "live.tsv is missing or lacks its header line"; exit 1; }
bad=$(awk -F'\t' 'NR>1 && (NF<3 || $3 !~ /^(pass|fail|n\/a)$/ || ($3 != "pass" && $4 == ""))' $f | head -3); [ -z "$bad" ] || { echo "rows need surface, ref, pass|fail|n/a, and a reason unless pass: $bad"; exit 1; }
for s in $S; do awk -F'\t' -v s=$s '$1==s && $2=="base" {f=1} END {exit !f}' $f || { echo "no base row for $s"; exit 1; }; done
for n in $(grep -o 'pull/[0-9]*' $up 2>/dev/null | sed 's|pull/|pr|') $(awk -F'\t' '$3=="merge" {print $2}' $al 2>/dev/null); do
  awk -F'\t' -v n=$n '$2==n {f=1} END {exit !f}' $f || { echo "no live row for $n"; exit 1; }
  grep -Eq "pull/${n#pr}([^0-9]|$)" .moor/artifacts/for-a-person.md || { echo "for-a-person.md does not link $n"; exit 1; }
done; echo "every surface has a base row and every PR to merge was tested"
